#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    // No arguments besides program name
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    // Only x provided, no coefficients
    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }
    // More than 12 coefficients (program name + x + 12 coeffs = 14 args)
    if (argc > 14) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Parse x
    char *endptr;
    long long x = strtoll(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    int coeff_cnt = argc - 2; // number of coefficients
    long long coeff[12];
    for (int i = 0; i < coeff_cnt; ++i) {
        char *e;
        long long c = strtoll(argv[2 + i], &e, 10);
        if (*e != '\0') {
            puts("BAD_INPUT");
            return 0;
        }
        if (c < -1000LL || c > 1000LL) {
            puts("OUT_OF_RANGE");
            return 0;
        }
        coeff[i] = c;
    }

    // Horner's method: coefficients are given from highest degree to constant term
    long long result = 0;
    for (int i = 0; i < coeff_cnt; ++i) {
        result = result * x + coeff[i];
    }
    printf("%lld\n", result);
    return 0;
}
